bool async_context_base_add_at_time_worker(async_context_t *self, async_at_time_worker_t *worker) {
 async_at_time_worker_t **prev = &self->at_time_list;
 while (*prev) {
 if (worker == *prev) {
 return false;
 }
 prev = &(*prev)->next;
 }
 *prev = worker;
 worker->next = NULL;
 return true;
}

