documents.detail:
C语言文件操作与数据处理

一、文件操作基础
1. 文件指针
 FILE *fp;

2. 文件打开
 fp = fopen("file.txt", "r"); // 只读
 fp = fopen("file.txt", "w"); // 只写
 fp = fopen("file.txt", "a"); // 追加
 fp = fopen("file.txt", "rb"); // 二进制读

3. 文件关闭
 fclose(fp);

4. 错误处理
 if (fp == NULL) {
 perror("Error opening file");
 return -1;
 }

二、文件读写
1. 字符读写
 // 读取字符
 int ch = fgetc(fp);

// 写入字符
 fputc('A', fp);

2. 字符串读写
 // 读取字符串
 char buf[100];
 fgets(buf, 100, fp);

// 写入字符串
 fputs("Hello", fp);

3. 格式化读写
 // 格式化读取
 int age;
 float score;
 fscanf(fp, "%d %f", &age, &score);

// 格式化写入
 fprintf(fp, "%d %.1f", age, score);

4. 数据块读写
 // 读取数据块
 int arr[10];
 fread(arr, sizeof(int), 10, fp);

// 写入数据块
 fwrite(arr, sizeof(int), 10, fp);

三、文件定位
1. fseek
 fseek(fp, 0, SEEK_SET); // 定位到文件开头
 fseek(fp, 0, SEEK_END); // 定位到文件末尾
 fseek(fp, 10, SEEK_CUR); // 从当前位置后移10字节

2. ftell
 long pos = ftell(fp); // 获取当前位置

