eth_mac_irq()
{
 /* Service MAC IRQ here */

/* Allocate pbuf from pool (avoid using heap in interrupts) */
 struct pbuf* p = pbuf_alloc(PBUF_RAW, eth_data_count, PBUF_POOL);

if(p != NULL) {
