 {
 static int dev;
 struct snd_card *card;
 struct mychip *chip;
 int err;

/* (1) */
 if (dev >= SNDRV_CARDS)
 return -ENODEV;
 if (!enable[dev]) {
 dev++;
 return -ENOENT;
 }

/* (2) */
 err = snd_card_new(&pci->dev, index[dev], id[dev], THIS_MODULE,
 0, &card);
 if (err < 0)
 return err;

/* (3) */
 err = snd_mychip_create(card, pci, &chip);
 if (err < 0)
 goto error;

