#include "pico/bit_ops.h"

uint32_t __rev(uint32_t v) {
 v = ((v & 0x55555555u) << 1u) | ((v >> 1u) & 0x55555555u);
 v = ((v & 0x33333333u) << 2u) | ((v >> 2u) & 0x33333333u);
 v = ((v & 0x0f0f0f0fu) << 4u) | ((v >> 4u) & 0x0f0f0f0fu);
 return (v << 24u) | ((v & 0xff00u) << 8u) | ((v >> 8u) & 0xff00u) | (v >> 24u);
}

